import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const Wizard = () => {
  const [steps, setSteps] = useState([1]);
  const navigate = useNavigate();

  const handleNextStep = () => {
    const nextStep = [...steps];
    nextStep.push(steps.length + 1);
    setSteps(nextStep);
  };

  const handlePreviousStep = () => {
    const previousStep = steps.filter((step) => step !== steps[0]);
    setSteps(previousStep);
  };

  return (
    <div>
      {steps.map((step) => (
        <div key={step} style={{ border: '1px solid #ccc', padding: 20, margin: 20 }}>
          <h3>Step {step}</h3>
          <p>Step {step} content...</p>
          {step < steps.length && <button onClick={handleNextStep}>Next</button>}
          {step > 1 && <button onClick={handlePreviousStep}>Previous</button>}
