function convertToFormal(sentence) {
    // Convert to proper case (capitalize the first letter of each word)
    sentence = sentence.replace(/(^| )([a-z])/g, (match, p1, p2) => p1 + p2.toUpperCase());

    // Replace common informal contractions with formal equivalents
    const informalContractions = [
        ['I\'m', 'I am'],
        ['you\'re', 'you are'],
        ['we\'re', 'we are'],
        ['they\'re', 'they are'],
        ['he\'s', 'he is'],
        ['she\'s', 'she is'],
        ['it\'s', 'it is'],
        ['that\'s', 'that is'],
        ['what\'s', 'what is'],
        ['where\'s', 'where is'],
        ['when\'s', 'when is'],
        ['who\'s', 'who is'],
        ['there\'s', 'there is'],
        ['couldn\'t', 'could not'],
        ['can\'t', 'cannot'],
        ['won\'t', 'will not'],
        ['shouldn\'t', 'should not'],
        ['wouldn\'t', 'would not'],
        ['didn\'t', 'did not'],
        ['haven\'t', 'have not'],
        ['hasn\'t', 'has not']
    ];

    informalContractions.forEach(([informal, formal]) => {
        sentence = sentence.replace(new RegExp(informal, 'gi'), formal);
    });

    // Remove unnecessary contractions
    sentence = sentence.replace(/\b(can't)\b/g, "cannot");
    sentence = sentence.replace(/\b(won't)\b/g, "will not");
    sentence = sentence.replace(/\b(wouldn't)\b/g, "would not");
    sentence = sentence.replace(/\b(didn't)\b/g, "did not");
    sentence = sentence.replace(/\b(hasn't)\b/g, "has not");
    sentence = sentence.replace(/\b(haven't)\b/g, "have not");
    sentence = sentence.replace(/\b(shouldn't)\b/g, "should not");
    sentence = sentence.replace(/\b(shan't)\b/g, "shall not");
    sentence = sentence.replace(/\b(aren't)\b/g, "are not");
    sentence = sentence.replace(/\b(isn't)\b/g, "is not");

    // Add punctuation if needed
    if (!/\.$/.test(sentence)) {
        sentence += '.';
    }

    return sentence;
}

// Example usage:
