### JavaScript (script.js)
```javascript
let draggableDiv = document.getElementById('draggableDiv');
let isDragging = false;

// Set initial positions
const initPosition = { x: parseInt(window.getComputedStyle(draggableDiv).getPropertyValue('left').replace('px', '')),
                        y: parseInt(window.getComputedStyle(draggableDiv).getPropertyValue('top').replace('px', '')) };

draggableDiv.addEventListener('mousedown', function(e) {
    isDragging = true;
    draggableDiv.style.zIndex = '1000'; // Place above other elements
    const pos = e.clientX;
    const pos2 = e.clientY;

    document.addEventListener('mousemove', onDrag);
    document.addEventListener('mouseup', stopDrag);

    function onDrag(e) {
        draggableDiv.style.left = (e.clientX - pos + initPosition.x) + 'px';
        draggableDiv.style.top = (e.clientY - pos2 + initPosition.y) + 'px';
    }
});

function stopDrag() {
    isDragging = false;
    document.removeEventListener('mousemove', onDrag);
    document.removeEventListener('mouseup', stopDrag);
}

document.addEventListener('mouseup', function () {
    if (!isDragging) return; // Make sure dragging has started

    // Reset the div's position when mouse button is released
    draggableDiv.style.left = `${initPosition.x}px`;
    draggableDiv.style.top = `${initPosition.y}px`;
});
```

### Explanation:
1. **HTML**: A simple HTML file that includes the draggable `div`.
2. **CSS**: Basic styling for the `div` to make it look like it can be dragged.
3. **JavaScript**:
   - We capture the initial position of the `div`.
   - When the user clicks (`mousedown`) on the `div`, we start tracking mouse movements.
   - As the user drags the `div`, we update its position based on the difference between the current mouse position and the click position.
   - When the user releases the mouse (`mouseup`), we reset the `div`'s position to the initial one.

